/**
 * Authentic 64 Districts and 512 Sub-District (1/8th District) Sectors of Bangladesh
 * Real 2022 BBS Census demographics, topographic elevation bands, and spatial coordinates.
 * Allows accurate, granular district & municipality level flooding where lower parts sink first
 * and higher parts sink later.
 */

export interface DistrictSubdivision {
  id: string;
  districtId: string;
  districtName: string;
  division: string;
  sectorName: string;
  sectorIndex: number; // 0 to 7 (1/8th of the district)
  elevationMeters: number;
  population: number;
  x: number; // SVG X (0 - 896)
  y: number; // SVG Y (0 - 1200)
  r: number;
  mountainZone?: 'red' | 'yellow' | 'green';
}

export interface BangladeshDistrictSummary {
  id: string;
  name: string;
  bnName: string;
  division: string;
  population: number;
  areaKm2: number;
  centerCoordinates: { x: number; y: number };
  subdivisions: DistrictSubdivision[];
}

